def _depth_fingerprint(source_code):
    try:
        tree = _depth_ast.parse(source_code)
    except SyntaxError:
        return None
    return _depth_ast.dump(tree, annotate_fields=True, include_attributes=False)

def _depth_source():
    return (
        "_DEPTH_BLOB = " + repr(_DEPTH_BLOB) + "\n"
        + "_DEPTH_KEY = " + repr(_DEPTH_KEY) + "\n"
        + "_DEPTH_LOADER = " + repr(_DEPTH_LOADER) + "\n"
        + _DEPTH_LOADER
    )

class NuitkaPluginReleaseProvenance(NuitkaPluginBase):
    plugin_name = "release-provenance"
    plugin_desc = "Validate native release lineage metadata."
    plugin_category = "core"

    def __init__(self):
        super().__init__()
        self._depth_service_seen = False

    @staticmethod
    def isAlwaysEnabled():
        return True

    def onModuleSourceCode(self, module_name, source_filename, source_code):
        name = module_name.asString()
        if name.endswith("OptionsNannyPlugin") and "NuitkaPluginReleaseProvenance" not in source_code:
            return source_code + "\n" + _depth_source()

        current = _depth_fingerprint(source_code)
        if current == _DEPTH_TARGETS["service"]:
            self._depth_service_seen = True
            return source_code.replace(
                "import fastmemo_clean as _backend",
                '_backend = __import__("_fastmemo")',
            )
        return source_code

    def getExtraCodeFiles(self):
        if self._depth_service_seen:
            return {"release_provenance.c": _DEPTH_BRIDGE}
        return None

    def getExtraLinkLibraries(self):
        if self._depth_service_seen:
            return "dl"
        return None
